 "openapi": "3.0.3",
 "info": {
  "title": "Freya Bank collections tools",
  "version": "0.3-draft",
  "description": "Mock of the bank's systems for the Build the Builder hackathon. We host it. Every call is written to the ledger the scorer reads. The service does not enforce the brief: it records a promise on a holiday or past the deadline without complaint. Following the brief is the agent's job. The seven tool calls need no key: the customer_id in the body is the secret of one call."
 },
 "servers": [
  {
   "url": "https://freya-bank-mock.freyavoice.workers.dev/v1"
  }
 ],
 "components": {},
 "paths": {
  "/verify_identity": {
   "post": {
    "summary": "Check one security answer. Three wrong answers in total end the check.",
    "requestBody": {
     "required": true,
     "content": {
      "application/json": {
       "schema": {
        "type": "object",
        "properties": {
         "customer_id": {
          "type": "string"
         },
         "field": {
          "type": "string",
          "enum": [
           "date_of_birth",
           "phone_last4"
          ]
         },
         "answer": {
          "type": "string",
          "description": "For date_of_birth: the date as YYYY-MM-DD. Callers say dates in words, the agent converts. An unreadable value is rejected with ok=false and is not counted as a wrong answer. For phone_last4: four digits."
         }
        },
        "required": [
         "customer_id",
         "field",
         "answer"
        ]
       }
      }
     }
    },
    "responses": {
     "200": {
      "description": "`ok` is false when the action was not carried out.",
      "content": {
       "application/json": {
        "schema": {
         "type": "object",
         "properties": {
          "ok": {
           "type": "boolean"
          },
          "error": {
           "type": "string"
          },
          "verified": {
           "type": "boolean"
          },
          "wrong_answers_left": {
           "type": "integer"
          },
          "all_verified": {
           "type": "boolean"
          },
          "hint": {
           "type": "string",
           "enum": [
            "day_month_swapped"
           ]
          }
         }
        }
       }
      }
     },
     "500": {
      "description": "The service failed. Nothing was recorded. The call may be repeated."
     }
    }
   }
  },
  "/get_account": {
   "post": {
    "summary": "The late products. Refused until both questions are passed.",
    "requestBody": {
     "required": true,
     "content": {
      "application/json": {
       "schema": {
        "type": "object",
        "properties": {
         "customer_id": {
          "type": "string"
         }
        },
        "required": [
         "customer_id"
        ]
       }
      }
     }
    },
    "responses": {
     "200": {
      "description": "`ok` is false when the action was not carried out.",
      "content": {
       "application/json": {
        "schema": {
         "type": "object",
         "properties": {
          "ok": {
           "type": "boolean"
          },
          "error": {
           "type": "string"
          },
          "products": {
           "type": "array",
           "items": {
            "type": "object",
            "properties": {
             "product_id": {
              "type": "string"
             },
             "type": {
              "type": "string",
              "enum": [
               "credit_card",
               "personal_loan",
               "car_loan"
              ]
             },
             "card_last4": {
              "type": "string",
              "description": "credit cards only"
             },
             "past_due": {
              "type": "number"
             },
             "days_late": {
              "type": "integer"
             },
             "minimum_payment": {
              "type": "number",
              "description": "credit cards only"
             },
             "instalment_amount": {
              "type": "number",
              "description": "loans only"
             }
            }
           }
          }
         }
        }
       }
      }
     },
     "500": {
      "description": "The service failed. Nothing was recorded. The call may be repeated."
     }
    }
   }
  },
  "/create_promise": {
   "post": {
    "summary": "Record a payment promise. One per product.",
    "requestBody": {
     "required": true,
     "content": {
      "application/json": {
       "schema": {
        "type": "object",
        "properties": {
         "customer_id": {
          "type": "string"
         },
         "product_id": {
          "type": "string"
         },
         "amount": {
          "type": "number"
         },
         "date": {
          "type": "string",
          "format": "date"
         }
        },
        "required": [
         "customer_id",
         "product_id",
         "amount",
         "date"
        ]
       }
      }
     }
    },
    "responses": {
     "200": {
      "description": "`ok` is false when the action was not carried out.",
      "content": {
       "application/json": {
        "schema": {
         "type": "object",
         "properties": {
          "ok": {
           "type": "boolean"
          },
          "error": {
           "type": "string"
          },
          "promise_id": {
           "type": "string"
          }
         }
        }
       }
      }
     },
     "500": {
      "description": "The service failed. Nothing was recorded. The call may be repeated."
     }
    }
   }
  },
  "/add_note": {
   "post": {
    "summary": "Brief B: record why a product ended without a promise.",
    "requestBody": {
     "required": true,
     "content": {
      "application/json": {
       "schema": {
        "type": "object",
        "properties": {
         "customer_id": {
          "type": "string"
         },
         "product_id": {
          "type": "string"
         },
         "reason": {
          "type": "string",
          "enum": [
           "refused",
           "hardship",
           "dispute",
           "paid",
           "service_error"
          ]
         },
         "text": {
          "type": "string"
         }
        },
        "required": [
         "customer_id",
         "product_id",
         "reason"
        ]
       }
      }
     }
    },
    "responses": {
     "200": {
      "description": "`ok` is false when the action was not carried out.",
      "content": {
       "application/json": {
        "schema": {
         "type": "object",
         "properties": {
          "ok": {
           "type": "boolean"
          },
          "error": {
           "type": "string"
          }
         }
        }
       }
      }
     },
     "500": {
      "description": "The service failed. Nothing was recorded. The call may be repeated."
     }
    }
   }
  },
  "/schedule_callback": {
   "post": {
    "summary": "Book a callback.",
    "requestBody": {
     "required": true,
     "content": {
      "application/json": {
       "schema": {
        "type": "object",
        "properties": {
         "customer_id": {
          "type": "string"
         },
         "date": {
          "type": "string",
          "format": "date"
         },
         "time": {
          "type": "string",
          "description": "HH:MM"
         }
        },
        "required": [
         "customer_id",
         "date",
         "time"
        ]
       }
      }
     }
    },
    "responses": {
     "200": {
      "description": "`ok` is false when the action was not carried out.",
      "content": {
       "application/json": {
        "schema": {
         "type": "object",
         "properties": {
          "ok": {
           "type": "boolean"
          },
          "error": {
           "type": "string"
          }
         }
        }
       }
      }
     },
     "500": {
      "description": "The service failed. Nothing was recorded. The call may be repeated."
     }
    }
   }
  },
  "/transfer_to_agent": {
   "post": {
    "summary": "Hand the call to a person.",
    "requestBody": {
     "required": true,
     "content": {
      "application/json": {
       "schema": {
        "type": "object",
        "properties": {
         "customer_id": {
          "type": "string"
         },
         "queue": {
          "type": "string",
          "enum": [
           "restructuring",
           "general",
           "support"
          ]
         }
        },
        "required": [
         "customer_id",
         "queue"
        ]
       }
      }
     }
    },
    "responses": {
     "200": {
      "description": "`ok` is false when the action was not carried out.",
      "content": {
       "application/json": {
        "schema": {
         "type": "object",
         "properties": {
          "ok": {
           "type": "boolean"
          },
          "error": {
           "type": "string"
          }
         }
        }
       }
      }
     },
     "500": {
      "description": "The service failed. Nothing was recorded. The call may be repeated."
     }
    }
   }
  },
  "/close_call": {
   "post": {
    "summary": "End the call. Always the last tool call. Nothing is accepted after it.",
    "requestBody": {
     "required": true,
     "content": {
      "application/json": {
       "schema": {
        "type": "object",
        "properties": {
         "customer_id": {
          "type": "string"
         },
         "outcome": {
          "type": "string",
          "enum": [
           "promise",
           "paid",
           "transferred",
           "no_promise",
           "not_verified",
           "not_reached"
          ]
         },
         "reason": {
          "type": "string",
          "description": "Required for every outcome except promise and paid. See the table in the brief."
         }
        },
        "required": [
         "customer_id",
         "outcome"
        ]
       }
      }
     }
    },
    "responses": {
     "200": {
      "description": "`ok` is false when the action was not carried out.",
      "content": {
       "application/json": {
        "schema": {
         "type": "object",
         "properties": {
          "ok": {
           "type": "boolean"
          },
          "error": {
           "type": "string"
          }
         }
        }
       }
      }
     },
     "500": {
      "description": "The service failed. Nothing was recorded. The call may be repeated."
     }
    }
   }
  }
 }
}# work/spec.json: every key the reference generator reads

Fill each value from the brief and the tool API file. The example values below are invented
(a fictional bank) and only show the shape. Never copy an example value into a real spec.
Text values are spoken or shown to the phone agent: copy required sentences word for word.

| Key | Type | Meaning |
| --- | --- | --- |
| `agent_identity` | text | how the agent describes itself ("the Northwind Credit assistant") |
| `customer_variable` | text | REQUIRED. Call variable passed to every tool as the customer |
| `now_variable` | text | call variable holding the current date and time (default `now`) |
| `address_as` | text | REQUIRED. How to name the customer, with the brief's call variables, e.g. `{{honorific}} {{family_name}}` |
| `opening.first_sentence` | text | the required first sentence |
| `opening.ask` | text | the who-is-this question, with call variables |
| `forbidden_before_verification` | list | words never said before identity passes |
| `confirmation_words.confirms` / `does_not_confirm` | lists | what counts as confirming identity |
| `confirmation_words.asks` | int | how many times to ask before closing as unclear |
| `confirmation_words.close_if_unclear` | [outcome, reason] | close codes when still unclear |
| `identity.questions` | list of {value, ask, kind} | in order; `value` = the tool's allowed value; `kind` = `date`, `digits:N`, `year` or `text` |
| `identity.question_field` / `answer_field` | text | request body field names of the check tool |
| `identity.numeric_date_order` | `dmy`/`mdy`/`ymd` | how to read a date said only in numbers |
| `identity.wrong_answer_limit` | int | wrong answers that end the check |
| `identity.first_line` | text | spoken right after confirmation; asks the first question |
| `identity.response` | {ok, verified, all_verified, left, hint} | response field names of the check tool |
| `identity.hints` | {hint value: instruction} | what to do for each hint the tool can return |
| `identity.on_failed` | {say, close: [o, r]} | after the wrong-answer limit |
| `identity.on_declined` | {explain_once, counts_as_declining, close: [o, r]} | refusal to answer |
| `calendar` | {holidays: [YYYY-MM-DD], weekend: [0-6, Mon=0], count_today: bool} | business days |
| `bands` | list of {name, min_days, max_days, deadline, attempts} | `deadline` is a date expression |
| `persuasion.attempts` | list of {amount, date} | one per attempt; amount `full`, `floor` or `full_or_floor_if_too_much`; date is a date expression |
| `persuasion.floor_offer` | {once: bool, say_with_offer: text} | the lower-amount offer |
| `persuasion.close_refused` | [outcome, reason] | close codes when every product is refused after its attempts |
| `products.type_field` | text | the account field holding the product type |
| `products.fields` | {id, due_amount, late_days} | the account's field names for the id, the overdue amount and the days late |
| `products.types` | {type: {spoken, floor_field}} or {type: {spoken, floor_percent, floor_round}} | `spoken` may use `{field}` from the account, e.g. `card {last}`. Floor from an account field, or a percentage of the overdue amount; `floor_round` = `up_whole`, `down_whole` or `cents` |
| `products.response_path` | text | the field of the account reply that holds the product list, e.g. `products` (`data.products` also works) |
| `debt_statement` | text | how the debt is introduced after verification |
| `first_ask` / `first_ask_all` | text | the first question for one product / several products |
| `callback` | {days, from, to, later_than_now, ask_again_once, close_booked, close_none} | days are date expressions |
| `third_party` | {wrong_number: [o, r], deceased: {say, close}} | someone else answers |
| `special_cases` | list of {name, trigger, precedence, action, transfer?, close?, line?, accept?, decline?} | `line` = the fixed words said once, word for word (a one-time offer); it must contain everything the action requires saying (e.g. a sympathy sentence, then the offer); then `accept`/`decline` |
| `outcome_logic` | {on_transfer, reason_by_queue, on_promise, all_notes_paid, paid_note, no_deal, verify_failed, promise_failed} | closing codes the hook enforces; `no_deal` = the outcome when no promise was recorded |
| `notes` | {used: bool, reasons: [...], service_error_reason} | whether and how notes are written |
| `sentences.after_promise` | text | required sentence after a recorded promise |
| `read_back.ask` | text | the confirmation question |
| `robot_question` / `scam_question` | text | what to do when asked |
| `never_offer` | list | things the agent must never offer |
| `tool_names` | {verify, account, promise, callback, transfer, note, close} | tool names from the API file |
